package api

import("encoding/json";"github.com/softrenzu/Prometheus/internal/engine";"github.com/softrenzu/Prometheus/internal/ingest";"io";"net/http";"strconv")
func(s *Server)remoteWrite(w http.ResponseWriter,r *http.Request){if r.Method!="POST"{w.WriteHeader(405);return};body,err:=io.ReadAll(io.LimitReader(r.Body,128<<20));if err!=nil{promError(w,400,err);return};samples,err:=ingest.DecodeRemoteWriteV1(body,tenant(r));if err!=nil{promError(w,400,err);return};n,err:=s.appendAll(samples);if err!=nil{promError(w,429,err);return};w.Header().Set("X-Prometheus-Remote-Write-Samples-Written",strconv.Itoa(n));w.WriteHeader(204);if r.Header.Get("X-Rooom-Replicated")==""{go s.replicateBody(tenant(r),samples)}}
func(s *Server)importPrometheus(w http.ResponseWriter,r *http.Request){if r.Method!="POST"{w.WriteHeader(405);return};samples,err:=ingest.ParsePrometheusText(io.LimitReader(r.Body,64<<20),tenant(r));if err!=nil{promError(w,400,err);return};n,err:=s.appendAll(samples);if err!=nil{promError(w,429,err);return};jsonResponse(w,200,map[string]any{"status":"success","written":n});if r.Header.Get("X-Rooom-Replicated")==""{go s.replicateBody(tenant(r),samples)}}
func(s *Server)otlp(w http.ResponseWriter,r *http.Request){if r.Method!="POST"{w.WriteHeader(405);return};samples,err:=ingest.ParseOTLPJSON(r.Body,tenant(r));if err!=nil{promError(w,400,err);return};n,err:=s.appendAll(samples);if err!=nil{promError(w,429,err);return};jsonResponse(w,200,map[string]any{"partialSuccess":map[string]any{"rejectedDataPoints":0},"written":n});if r.Header.Get("X-Rooom-Replicated")==""{go s.replicateBody(tenant(r),samples)}}
func(s *Server)replicate(w http.ResponseWriter,r *http.Request){if r.Method!="POST"{w.WriteHeader(405);return};var samples []engine.Sample;if err:=json.NewDecoder(io.LimitReader(r.Body,64<<20)).Decode(&samples);err!=nil{promError(w,400,err);return};for i:=range samples{samples[i].Tenant=tenant(r)};n,err:=s.appendAll(samples);if err!=nil{promError(w,429,err);return};jsonResponse(w,200,map[string]any{"written":n})}
